statement:
Given an integer array `nums` and a value `pivot` that occurs in it, return a rearrangement of `nums` made of three consecutive blocks:

- first, all values smaller than `pivot`, in the same order they had in `nums`;
- then every value equal to `pivot`;
- last, all values larger than `pivot`, again in their original order.

Because the order inside the smaller and larger blocks is fixed, exactly one arrangement is correct.

validator:
function validate([nums, pivot]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000 || v > 1000000)) return 'Each value is between -10^6 and 10^6.';
  if (!nums.includes(pivot)) return 'pivot must be one of the values in nums.';
  return null;
}

reference:
function pivotArray(nums, pivot) {
  let less = 0;
  let equal = 0;
  for (const value of nums) {
    if (value < pivot) {
      less++;
    } else if (value === pivot) {
      equal++;
    }
  }

  const result = new Array(nums.length).fill(pivot);
  let low = 0;
  let high = less + equal;
  for (const value of nums) {
    if (value < pivot) {
      result[low] = value;
      low++;
    } else if (value > pivot) {
      result[high] = value;
      high++;
    }
  }
  return result;
}

brute:
function pivotArray(nums, pivot) {
  const smaller = nums.filter(v => v < pivot);
  const same = nums.filter(v => v === pivot);
  const larger = nums.filter(v => v > pivot);
  return smaller.concat(same, larger);
}

generator:
function generate(rand, size) {
  const n = size === 'large' ? 2000 - Math.floor(rand() * 30) : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? (rand() < 0.5 ? 1000000 : 50) : 1 + Math.floor(rand() * 6);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  if (rand() < 0.1) nums[Math.floor(rand() * n)] = rand() < 0.5 ? -1000000 : 1000000;
  // pivot must be one of the values.
  const pivot = nums[Math.floor(rand() * n)];
  return [nums, pivot];
}
